document.addEventListener("DOMContentLoaded",function(){const e=[...document.querySelectorAll("[data-bg]")];if("IntersectionObserver"in window){const t=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){const r=e.target;r.style.backgroundImage=`url('${r.dataset.bg}')`,r.removeAttribute("data-bg"),t.unobserve(r)}})});e.forEach(e=>t.observe(e))}else e.forEach(e=>{e.style.backgroundImage=`url('${e.dataset.bg}')`,e.removeAttribute("data-bg")})});